import { Composio, SchemaModifier } from '@composio/core';
import * as fs from 'fs';

async function main() {
  // Create a SchemaModifier to hide the 'text' argument from Slack's chat_post_message tool
  const modifier = new SchemaModifier().hide('slack', 'chat_post_message', ['text']);

  // Create Composio instance with the modifier
  const composio = new Composio();

  // Create session for zealt-user01 with the modifier
  const session = composio.create('zealt-user01', { modifiers: [modifier] });

  // Retrieve tools from the session
  const tools = await session.tools();

  // Find the Slack post message tool
  const slackTool = tools.find(tool => 
    tool.name === 'chat_post_message' || 
    tool.name === 'SLACK_CHAT_POST_MESSAGE'
  );

  if (!slackTool) {
    console.error('Slack post message tool not found');
    process.exit(1);
  }

  // Write the modified tool's schema to /home/user/schema.json
  fs.writeFileSync('/home/user/schema.json', JSON.stringify(slackTool.inputSchema, null, 2));

  console.log('Modified schema written to /home/user/schema.json');
  console.log('Schema:', JSON.stringify(slackTool.inputSchema, null, 2));
}

main().catch(console.error);

