import { Composio } from '@composio/core';
import * as fs from 'fs';

// Simple SchemaModifier class that provides the hide method
class SchemaModifier {
  private modifications: Map<string, string[]> = new Map();

  hide(toolkitSlug: string, toolSlug: string, properties: string[]): this {
    const key = `${toolkitSlug}:${toolSlug}`;
    this.modifications.set(key, properties);
    return this;
  }

  shouldHide(toolkitSlug: string, toolSlug: string, property: string): boolean {
    const key = `${toolkitSlug}:${toolSlug}`;
    const propertiesToHide = this.modifications.get(key) || [];
    return propertiesToHide.includes(property);
  }
}

async function main() {
  // Create a SchemaModifier to hide the 'text' argument from Slack's chat_post_message tool
  const modifier = new SchemaModifier().hide('slack', 'chat_post_message', ['text']);

  // Create Composio instance
  const composio = new Composio();

  // Create session for zealt-user01
  const session = await composio.create('zealt-user01', {
    toolkits: ['slack']
  });

  // Retrieve tools from the session with schema modification
  const tools = await session.tools({
    modifySchema: ({ toolSlug, toolkitSlug, schema }) => {
      // Check if this tool needs modification
      if (modifier.shouldHide(toolkitSlug, toolSlug, 'text')) {
        // Remove the 'text' property from the schema
        const modifiedSchema = { ...schema };
        if (modifiedSchema.inputParameters && modifiedSchema.inputParameters.properties) {
          const { text, ...remainingProperties } = modifiedSchema.inputParameters.properties;
          modifiedSchema.inputParameters.properties = remainingProperties;

          // Remove 'text' from required array if present
          if (modifiedSchema.inputParameters.required) {
            modifiedSchema.inputParameters.required = modifiedSchema.inputParameters.required.filter(
              (prop: string) => prop !== 'text'
            );
          }
        }
        return modifiedSchema;
      }
      return schema;
    }
  });

  // Find the Slack post message tool
  const slackTool = tools.find((tool: any) => 
    tool.name === 'chat_post_message' || 
    tool.name === 'SLACK_CHAT_POST_MESSAGE' ||
    tool.slug === 'chat_post_message'
  );

  if (!slackTool) {
    console.error('Slack post message tool not found');
    console.log('Available tools:', tools.map((t: any) => ({ name: t.name, slug: t.slug })));
    process.exit(1);
  }

  // Write the modified tool's schema to /home/user/schema.json
  const schemaToWrite = slackTool.inputSchema || slackTool.inputParameters;
  fs.writeFileSync('/home/user/schema.json', JSON.stringify(schemaToWrite, null, 2));

  console.log('Modified schema written to /home/user/schema.json');
  console.log('Schema:', JSON.stringify(schemaToWrite, null, 2));
}

main().catch(console.error);

