import { Composio } from '@composio/core';
import * as fs from 'fs';

// Simple SchemaModifier class that provides the hide method
class SchemaModifier {
  private modifications: Map<string, string[]> = new Map();

  hide(toolkitSlug: string, toolSlug: string, properties: string[]): this {
    const key = `${toolkitSlug}:${toolSlug}`;
    this.modifications.set(key, properties);
    return this;
  }

  shouldHide(toolkitSlug: string, toolSlug: string, property: string): boolean {
    const key = `${toolkitSlug}:${toolSlug}`;
    const propertiesToHide = this.modifications.get(key) || [];
    return propertiesToHide.includes(property);
  }
}

async function main() {
  // Create a SchemaModifier to hide the 'text' argument from Slack's chat_post_message tool
  const modifier = new SchemaModifier().hide('slack', 'chat_post_message', ['text']);

  // Create Composio instance
  const composio = new Composio();

  // Create session for zealt-user01
  const session = await composio.create('zealt-user01', {
    toolkits: ['slack']
  });

  // Search for the Slack tool
  const searchResults = await session.search({
    query: 'slack post message'
  });

  // Find the SLACK_SEND_MESSAGE tool (which is likely the chat_post_message tool)
  let slackTool: any = null;

  // Check toolSchemas for the tool
  if (searchResults.toolSchemas) {
    // Try different possible tool names
    const possibleNames = [
      'SLACK_SEND_MESSAGE',
      'chat_post_message', 
      'SLACK_CHAT_POST_MESSAGE',
      'SEND_MESSAGE'
    ];

    for (const name of possibleNames) {
      if (searchResults.toolSchemas[name]) {
        slackTool = searchResults.toolSchemas[name];
        console.log(`Found tool: ${name}`);
        break;
      }
    }
  }

  if (!slackTool) {
    console.error('Could not find Slack post message tool');
    console.log('Available tools in toolSchemas:', Object.keys(searchResults.toolSchemas || {}));
    process.exit(1);
  }

  // Apply the modification to hide the 'text' property
  const modifiedSchema = { ...slackTool.inputSchema };

  if (modifiedSchema.properties) {
    const { text, ...remainingProperties } = modifiedSchema.properties;
    modifiedSchema.properties = remainingProperties;

    // Remove 'text' from required array if present
    if (modifiedSchema.required) {
      modifiedSchema.required = modifiedSchema.required.filter(
        (prop: string) => prop !== 'text'
      );
    }
  }

  // Write the modified tool's schema to /home/user/schema.json
  fs.writeFileSync('/home/user/schema.json', JSON.stringify(modifiedSchema, null, 2));

  console.log('Modified schema written to /home/user/schema.json');
  console.log('Original schema had "text" property');
  console.log('Modified schema:', JSON.stringify(modifiedSchema, null, 2));
}

main().catch(console.error);

